  function renderCatalog(){const groups=tab==='all'?biomes:biomes.filter(b=>b.id===tab);grid.innerHTML=groups.flatMap(b=>squares.filter(s=>s.biome===b.id).map(s=>{let f=found[s.id];return `<article class="square-card ${f?'':'missing'}"><div class="square-icon" style="background:${s.color}"></div><div><h3>${f?s.name:'Unknown Square'}</h3><p>${f?b.name:s.hint}</p>${f?`<span class="found-date">FOUND ${f}</span>`:''}</div></article>`})).join('');$('#catalogTabs').innerHTML=[['all','All squares'],...biomes.map(b=>[b.id,b.name])].map(([id,label])=>`<button class="${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-tab="${id}">${label}</button>`).join('');$('#catalogTabs').querySelectorAll('button').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;renderCatalog()})}
